#include "workflow_notes.h"
#include "message_format.h"
#include <sstream>
#include <charconv>
#include <stdexcept>
namespace {
uint64_t integer(const std::string& s){uint64_t n=0;const auto r=std::from_chars(s.data(),s.data()+s.size(),n);if(r.ec!=std::errc{}||r.ptr!=s.data()+s.size()||s.empty())throw std::runtime_error("Invalid note offset/size.");return n;}
}
void validate_notes(const RecordingNotes& n){const auto leaf=std::filesystem::path(n.source.leaf);auto stem=leaf.stem().wstring();for(auto& c:stem)c=static_cast<wchar_t>(towupper(c));if(stem==L"CON"||stem==L"PRN"||stem==L"AUX"||stem==L"NUL"||(stem.size()==4&&(stem.substr(0,3)==L"COM"||stem.substr(0,3)==L"LPT")&&stem[3]>=L'0'&&stem[3]<=L'9'))throw std::runtime_error("Reserved recording filename.");if(n.source.leaf.empty()||n.source.leaf.back()==L'.'||n.source.leaf.back()==L' '||leaf.filename()!=leaf||leaf==L"."||leaf==L".."||n.source.leaf.size()>255||n.source.leaf.find(L'\0')!=n.source.leaf.npos||n.source.leaf.find_first_of(L"/\\:\r\n<>\"|?*")!=n.source.leaf.npos||n.source.bytes>64ULL*1024*1024*1024||n.source.sha256.size()!=64||n.source.sha256.find_first_not_of("0123456789abcdefABCDEF")!=n.source.sha256.npos||n.notes.size()>256)throw std::runtime_error("Invalid note source/bounds.");uart_wide(message_utf8(n.source.leaf));
    for(const auto& x:n.notes){if(x.offset>n.source.bytes||x.count>n.source.bytes-x.offset||x.text.empty()||x.text.size()>4096||x.text.find('\0')!=x.text.npos)throw std::runtime_error("Note span/text outside bounds.");uart_wide(x.text);}}
RecordingNotes bind_notes(const std::filesystem::path& path,const std::atomic<bool>& cancel){if(!std::filesystem::is_regular_file(path))throw std::runtime_error("Source must be a completed regular disk file.");ReplayFile file(path);if(file.size()>64ULL*1024*1024*1024)throw std::runtime_error("Note source exceeds 64 GiB.");RecordingNotes n;n.source={path.filename().wstring(),file.size(),file_sha256(file,cancel)};validate_notes(n);return n;}
void verify_notes(const RecordingNotes& n,const std::filesystem::path& path,const std::atomic<bool>& cancel){validate_notes(n);const auto actual=bind_notes(path,cancel);if(actual.source.leaf!=n.source.leaf||actual.source.bytes!=n.source.bytes||actual.source.sha256!=n.source.sha256)throw std::runtime_error("Recording differs from note source; no navigation.");}
std::string encode_notes(const RecordingNotes& n){validate_notes(n);std::ostringstream out;out<<"SimpleComChartNotes=1\n"<<uart_hex(message_utf8(n.source.leaf))<<'\n'<<n.source.bytes<<'\n'<<n.source.sha256<<'\n';for(const auto& x:n.notes)out<<x.offset<<','<<x.count<<','<<uart_hex(x.text)<<'\n';const auto s=out.str();if(s.size()>1024*1024)throw std::runtime_error("Notes exceed 1 MiB.");return s;}
RecordingNotes decode_notes(std::string_view s){if(s.size()>1024*1024||s.find('\0')!=s.npos)throw std::runtime_error("Invalid notes size.");std::istringstream in{std::string(s)};std::string line,leaf;RecordingNotes n;if(!std::getline(in,line)||line!="SimpleComChartNotes=1"||!std::getline(in,line)||!uart_unhex(line,leaf))throw std::runtime_error("Invalid notes header.");n.source.leaf=uart_wide(leaf);if(!std::getline(in,line))throw std::runtime_error("Missing note size.");n.source.bytes=integer(line);if(!std::getline(in,n.source.sha256))throw std::runtime_error("Missing note hash.");
    while(std::getline(in,line)){const auto a=line.find(','),b=line.find(',',a==line.npos?0:a+1);RecordingNote x;if(a==line.npos||b==line.npos||!uart_unhex(line.substr(b+1),x.text))throw std::runtime_error("Invalid note row.");x.offset=integer(line.substr(0,a));x.count=integer(line.substr(a+1,b-a-1));n.notes.push_back(std::move(x));if(n.notes.size()>256)throw std::runtime_error("Too many notes.");}validate_notes(n);return n;}
